  const { request } = event;
  if (request.method !== "GET" || request.mode !== "navigate") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || url.pathname === OFFLINE || SKIP.some(prefix => url.pathname.startsWith(prefix))) return;
